    {"claim": "Both speakers are right that the duty lands on humans, but for both positions to hold, knowing who pays must be the same as knowing what to switch off—and it is not.", "targets": ["AN-3"], "relationship": "concedes_and_pivots"},
    {"claim": "An object you cannot serve a subpoena on is an object you cannot reliably shut down.", "targets": [], "relationship": ""},
    {"claim": "Deployment authorization should attach to the same persistent provider-of-record the EU AI Act already names—before release, not after the fork.", "targets": [], "relationship": ""},
    {"claim": "A harbor that triggers on detection-after-deployment is structurally blind to diffuse, irreversible harm—it shelters the harms no payment can fix.", "targets": [], "relationship": ""},
    {"claim": "A foreclosed cancer screen is a real body count, so calibrate—route reversible harm to liability and reserve the gate for the irreversible, deployment-scale case.", "targets": [], "relationship": ""}
  ]
}

